import pandas as pd
import requests
from datetime import datetime, timezone

now = datetime.now(timezone.utc)
now_epoch = int(now.timestamp())

EXPECTED_COLUMNS = [
    'volcano_number', 'volcano_name', 'region', 'subregion',
    'alert_level', 'color_code', 'latitude', 'longitude',
    'updated_date', 'severity_tier', 'aviation_risk',
    'economic_thesis', '_epoch',
]

def severity_from_alert(alert, color):
    a = (alert or '').upper()
    c = (color or '').upper()
    if a == 'WARNING' or c == 'RED':
        return 'CRITICAL'
    if a == 'WATCH' or c == 'ORANGE':
        return 'HIGH'
    if a == 'ADVISORY' or c == 'YELLOW':
        return 'MODERATE'
    return 'LOW'

def aviation_risk(color):
    c = (color or '').upper()
    if c == 'RED':
        return 'SEVERE - ongoing major eruption, airspace closure likely'
    if c == 'ORANGE':
        return 'HIGH - eruption imminent or minor ash emissions ongoing'
    if c == 'YELLOW':
        return 'ELEVATED - signs of unrest above background'
    return 'NORMAL'

def region_thesis(region_str):
    r = (region_str or '').upper()
    if 'ICELAND' in r:
        return 'European airspace disruption (IAG, LHA, Airbus orders delay risk)'
    if 'INDONES' in r:
        return 'Palm oil, nickel, rare-earth supply risk (BHP, nickel miners, EIDO)'
    if 'ALASKA' in r:
        return 'Trans-Pacific air cargo disruption (FDX cargo routes, UPS)'
    if 'JAPAN' in r:
        return 'Japan electronics supply + tourism impact (Sony, Toyota ADR, EWJ)'
    if 'CHILE' in r or 'SOUTH AMERICA' in r:
        return 'Chile copper / mining disruption (FCX, SCCO, ECH)'
    if 'HAWAI' in r:
        return 'Hawaii tourism impact (HGV, PK resort REITs)'
    if 'KAMCHAT' in r or 'RUSSIA' in r:
        return 'North Pacific air cargo (FDX, UPS transpacific routes)'
    if 'PHILIPPINES' in r:
        return 'Philippines BPO + semiconductor (EPHE, TEL)'
    if 'NEW ZEALAND' in r:
        return 'New Zealand tourism/agriculture (ENZL ETF)'
    if 'ITAL' in r or 'EUROPE' in r:
        return 'European aviation + southern-Italy economic exposure (EWI)'
    return 'Regional aviation/agriculture disruption - monitor for airspace advisories'

volcanoes = []
try:
    resp = requests.get(
        'https://volcanoes.usgs.gov/hans-public/api/volcano/getElevatedVolcanoes',
        headers={'User-Agent': 'speakesquery (macro-brief) ingestion', 'Accept': 'application/json'},
        timeout=30,
    )
    resp.raise_for_status()
    payload = resp.json()
    if isinstance(payload, list):
        volcanoes = payload
    elif isinstance(payload, dict):
        raw = payload.get('volcanoes') or payload.get('data') or []
        if isinstance(raw, list):
            volcanoes = raw
except Exception:
    volcanoes = []

rows = []
for vi in range(len(volcanoes)):
    vol = volcanoes[vi]
    if not isinstance(vol, dict):
        continue
    alert_raw = vol.get('alert_level')
    if alert_raw is None:
        alert_raw = vol.get('alertLevel')
    alert = str(alert_raw or '')
    color_raw = vol.get('color_code')
    if color_raw is None:
        color_raw = vol.get('colorCode')
    color = str(color_raw or '')
    severity = severity_from_alert(alert, color)
    if severity == 'LOW':
        continue
    lat_raw = vol.get('latitude')
    if lat_raw is None:
        lat_raw = vol.get('lat')
    lat = None
    if lat_raw is not None:
        try:
            lat = float(lat_raw)
        except Exception:
            lat = None
    lon_raw = vol.get('longitude')
    if lon_raw is None:
        lon_raw = vol.get('long')
    if lon_raw is None:
        lon_raw = vol.get('lng')
    lon = None
    if lon_raw is not None:
        try:
            lon = float(lon_raw)
        except Exception:
            lon = None
    region_str = str(vol.get('region', '') or '')
    vol_name = vol.get('volcano_name_en')
    if vol_name is None:
        vol_name = vol.get('volcanoName')
    if vol_name is None:
        vol_name = vol.get('name')
    vol_num = vol.get('vnum')
    if vol_num is None:
        vol_num = vol.get('volcano_number')
    upd = vol.get('updated_date')
    if upd is None:
        upd = vol.get('updatedDate')
    rows.append({
        'volcano_number': str(vol_num or ''),
        'volcano_name': str(vol_name or ''),
        'region': region_str,
        'subregion': str(vol.get('subregion', '') or ''),
        'alert_level': alert.upper(),
        'color_code': color.upper(),
        'latitude': lat,
        'longitude': lon,
        'updated_date': str(upd or ''),
        'severity_tier': severity,
        'aviation_risk': aviation_risk(color),
        'economic_thesis': region_thesis(region_str),
        '_epoch': now_epoch,
    })

if rows:
    df = pd.DataFrame(rows, columns=EXPECTED_COLUMNS)
else:
